function trap(h) {
  let l = 0, r = h.length - 1, lmax = 0, rmax = 0, res = 0;
  while (l < r) {
    if (h[l] < h[r]) { lmax = Math.max(lmax, h[l]); res += lmax - h[l++]; }
    else            { rmax = Math.max(rmax, h[r]); res += rmax - h[r--]; }
