```js
function spiral(m) {
  const res = [];
  let top = 0, bot = m.length - 1, l = 0, r = m[0].length - 1;
  while (top <= bot && l <= r) {
    for (let c = l; c <= r; c++) res.push(m[top][c]); top++;
    for (let rr = top; rr <= bot; rr++) res.push(m[rr][r]); r--;
    if (top <= bot) { for (let c = r; c >= l; c--) res.push(m[bot][c]); bot--; }
    if (l <= r) { for (let rr = bot; rr >= top; rr--) res.push(m[rr][l]); l++; }
  }
  return res;
}
```

