function maxProduct(nums) {
  let mx = nums[0], mn = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const n = nums[i];
    if (n < 0) [mx, mn] = [mn, mx];
    mx = Math.max(n, mx * n);
    mn = Math.min(n, mn * n);
