```js
function longestPalindrome(s) {
  let start = 0, len = 0;
  const exp = (l, r) => { while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; } return r - l - 1; };
  for (let i = 0; i < s.length; i++) {
    const a = exp(i, i), b = exp(i, i + 1), m = Math.max(a, b);
    if (m > len) { len = m; start = i - ((m - 1) >> 1); }
  }
  return s.slice(start, start + len);
}
```

