```js
function multiply(a, b) {
  if (a === '0' || b === '0') return '0';
  const res = new Array(a.length + b.length).fill(0);
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--) {
      const p = +a[i] * +b[j] + res[i + j + 1];
      res[i + j + 1] = p % 10;
      res[i + j] += p / 10 | 0;
    }
  return res.join('').replace(/^0+/, '');
}
