```js
function backspaceCompare(s, t) {
  const nxt = (str, i) => { let bk = 0; while (i >= 0) { if (str[i] === '#') { bk++; i--; } else if (bk) { bk--; i--; } else break; } return i; };
  let i = s.length - 1, j = t.length - 1;
  while (i >= 0 || j >= 0) {
    i = nxt(s, i); j = nxt(t, j);
    if ((s[i] || '') !== (t[j] || '')) return false;
    i--; j--;
  }
  return true;
}
```

